  /// Confirmation action when the current Blocks workspace is structurally empty.
  ///
  /// In en, this message translates to:
  /// **'Create blocks'**
  String get pythonBlocksCreate;

  /// Destructive confirmation action when imported Python will replace a nonempty Blocks workspace.
  ///
  /// In en, this message translates to:
  /// **'Replace workspace'**
  String get pythonBlocksReplace;

  /// Stale-candidate warning; the old preview is never committed.
  ///
  /// In en, this message translates to:
  /// **'The Editor source changed while the preview was being prepared. Convert again to review the latest code.'**
  String get pythonBlocksSourceChanged;

  /// Success announcement after production-host acknowledgement and explicit commit.
  ///
  /// In en, this message translates to:
  /// **'Blocks are ready. Nothing has been saved or run.'**
  String get pythonBlocksLoaded;

  /// Contained conversion/host failure. Reason is a technical exception identifier.
  ///
  /// In en, this message translates to:
  /// **'Could not prepare blocks: {reason}'**
  String pythonBlocksFailed(String reason);
}

class _AppLocalizationsDelegate
    extends LocalizationsDelegate<AppLocalizations> {
  const _AppLocalizationsDelegate();

  @override
  Future<AppLocalizations> load(Locale locale) {
    return SynchronousFuture<AppLocalizations>(lookupAppLocalizations(locale));
  }

  @override
  bool isSupported(Locale locale) =>
      <String>['en'].contains(locale.languageCode);

  @override
  bool shouldReload(_AppLocalizationsDelegate old) => false;
}

AppLocalizations lookupAppLocalizations(Locale locale) {
  // Lookup logic when only language code is specified.
  switch (locale.languageCode) {
    case 'en':
      return AppLocalizationsEn();
  }

  throw FlutterError(
    'AppLocalizations.delegate failed to load unsupported locale "$locale". This is likely '
    'an issue with the localizations generation tool. Please file an issue '
    'on GitHub with a reproducible sample app and the gen-l10n configuration '
    'that was used.',
  );
}
